	enum Tamper {
		ABSENT,
		MALFORMED,
		UNKNOWN_SCHEMA,
		NON_CANONICAL_TRANSACTION,
		NEGATIVE_TRANSACTION,
		UPPER_CASE_GENERATION,
		MISSING_GENERATION,
		TRANSACTION_PLUS_ONE,
		TRANSACTION_MINUS_ONE,
		GENERATION_DIFFERS
	}

	@ParameterizedTest
	@EnumSource(Tamper.class)
	void aWitnessThatDoesNotMatchMakesTheNextOpenReconcile(Tamper tamper) throws Exception {
		Path store = legacyStore();
		LmdbStoreConfig config = legacyConfig(false);
		session(store, config, this::addLanguageLiterals);
		String witness = witness(store);
		assertNotNull(witness, "fixture: a reconciled store closed cleanly");
		String[] fields = witness.split(":");
		long transaction = Long.parseLong(fields[1]);
		String generation = fields[2];
		String flipped = (generation.charAt(0) == '0' ? "1" : "0") + generation.substring(1);
		String tampered = switch (tamper) {
		case ABSENT -> null;
		case MALFORMED -> "not a witness";
		case UNKNOWN_SCHEMA -> "2:" + transaction + ":" + generation;
		case NON_CANONICAL_TRANSACTION -> "1:0" + transaction + ":" + generation;
		case NEGATIVE_TRANSACTION -> "1:-" + transaction + ":" + generation;
		case UPPER_CASE_GENERATION -> "1:" + transaction + ":" + generation.toUpperCase(Locale.ROOT);
		case MISSING_GENERATION -> "1:" + transaction + ":";
		case TRANSACTION_PLUS_ONE -> "1:" + (transaction + 1) + ":" + generation;
		case TRANSACTION_MINUS_ONE -> "1:" + (transaction - 1) + ":" + generation;
		case GENERATION_DIFFERS -> "1:" + transaction + ":" + flipped;
		};
		if (tamper == Tamper.UPPER_CASE_GENERATION) {
			assertNotEquals(generation, generation.toUpperCase(Locale.ROOT),
					"fixture: the generation has a hex letter");
		}
		if (tampered == null) {
			Files.delete(store.resolve(WITNESS_FILE));
		} else {
			Files.writeString(store.resolve(WITNESS_FILE), tampered, StandardCharsets.US_ASCII);
		}

		List<Step> steps = new CopyOnWriteArrayList<>();
		LmdbLanguageTagVariantMerge.stepObserverForTesting = steps::add;
		try (Session session = new Session(store, config)) {
			assertEquals(List.of(Step.PLANNED, Step.VALUES_MERGED), steps, tamper + " must not skip the reconcile");
			assertNull(witness(store), "a witness that does not match is withdrawn before startup writes");
		}
		LmdbLanguageTagVariantMerge.stepObserverForTesting = null;
		assertEquals("1:" + LmdbCompatibilityFixtures.nativeTransactionId(store) + ":" + generation(store),
				witness(store), "the completed reconcile is witnessed again at the clean close");
		assertEquals(List.of(), session(store, config, connection -> {
		}));
	}

